import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  // Create plane geometry with atlas region aspect ratio (512:320)
  const atlasAspectRatio = 512 / 320;
  const planeHeight = 1.0;
  const planeWidth = planeHeight * atlasAspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load sprite texture from asset URL
  const spriteTexture = ctx.textureLoader.load(config.imageUrl);
  spriteTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL texture node
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(spriteTexture);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from config
  if (config.position) {
    mesh.position.set(config.position.x, config.position.y, config.position.z);
  }
  if (config.rotation) {
    mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  }
  if (config.scale) {
    mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);
  }

  // Initialize event handlers and cleanup
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    spriteTexture.dispose();
  };

  return mesh;
}
